// Upstream's quest rules as its rule dialogs list them: name, help, category and related rules,
// for 2.55.17 and for 3.0 Nightly (zq_rule_names.cpp, generated by tools/zq_gen_rule_names.py).
// Rule numbers are the bit numbers 2.55 / 3.0 quests store.

#ifndef ZQ_RULE_NAMES_H
#define ZQ_RULE_NAMES_H

enum { ZQ_RULE_CATEGORIES = 16 };

// Categories 0-9 are quest rules (Animation ... Weapon), 10-14 ZScript rules, 15 the compiler
// settings that are stored as rules.
enum { ZQ_RULE_FIRST_SCRIPT_CATEGORY = 10 };

struct ZqRuleInfo
{
    short rule;
    signed char category;
    const char *name;
    const char *help;           // may be empty
    short related[4];           // rules the help refers to; -1: none
};

int zq_rule_count(bool is30);
const ZqRuleInfo &zq_rule_at(bool is30, int k);
const char *zq_rule_category(bool is30, int cat);
int zq_rule_max(bool is30);     // upstream's qr_MAX for the generation

// What a quest's rule section says about the quest, for upstream's readrules.
struct ZqRuleQuest
{
    int zelda_version, build;       // the header's
    int major, minor, patch;        // the header's program version
    const char *title, *author;
    int s_version;                  // the rule section's version
    unsigned long compat;           // its compat rule version (0 before section version 17)
};

// The updates upstream's readrules (the generation's) makes to the stored bits (100 bytes) as it
// loads them: compatibility rules turned on for quests older than they are, and so on.
void zq_rules_upstream(bool is30, unsigned char *rules, const ZqRuleQuest &q);

// The compat rule version the generation's own editor saves (every update above decided).
unsigned long zq_rules_latest_compat(bool is30);

#endif
